(7237774, 1120596, 156466, '<td valign="top">Nice colors but is extremely awkward compositionally.  I want to twist it hard left or right, just so long as it doesn''t stay the way it is.</td>', 'Nice colors but is extremely awkward compositionally.  I want to twist it hard left or right, just so long as it doesn''t stay the way it is.', '2014-07-07 09:54:03.000000', NULL, 1),
(7237775, 1119674, 156466, '<td valign="top">Nice photo but I''m not digging the processing or the lean to the right along the left edge.  Handled differently this could be stunning. 6 as is.</td>', 'Nice photo but I''m not digging the processing or the lean to the right along the left edge.  Handled differently this could be stunning. 6 as is.', '2014-07-07 09:56:13.000000', NULL, 1),
