INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7238049, 1120551, 147314, '<td valign="top">Fantastic sunset, great composition, beautiful colours and very well processed.</td>', 'Fantastic sunset, great composition, beautiful colours and very well processed.', '2014-07-07 17:50:44.000000', NULL, 1),
