(7238051, 1117697, 58634, '<td valign="top">I like the warmth here and the fac that it hasn''t been overdone.</td>', 'I like the warmth here and the fac that it hasn''t been overdone.', '2014-07-07 17:51:27.000000', NULL, 1),
(7238052, 1120511, 58634, '<td valign="top">Probably not the technically speaking strongest shot, however, you''ve captured and beautifully tender moment. Adorable, to say the least.</td>', 'Probably not the technically speaking strongest shot, however, you''ve captured and beautifully tender moment. Adorable, to say the least.', '2014-07-07 17:52:05.000000', NULL, 1),
(7238053, 1120670, 58634, '<td valign="top">So ghostly! I like.</td>', 'So ghostly! I like.', '2014-07-07 17:52:15.000000', NULL, 1),
