(7238094, 1120609, 58634, '<td valign="top">Too soft for my liking, needs a little bit of sharpness although the vintage tone is nice.</td>', 'Too soft for my liking, needs a little bit of sharpness although the vintage tone is nice.', '2014-07-07 19:22:30.000000', NULL, 1),
