(7238167, 1120047, 58634, '<td valign="top">This king looks unamused by you lol</td>', 'This king looks unamused by you lol', '2014-07-07 19:58:58.000000', NULL, 1),
(7238168, 1120522, 58634, '<td valign="top">I like the slight sepia and the camaraderie portrayed here.</td>', 'I like the slight sepia and the camaraderie portrayed here.', '2014-07-07 19:59:55.000000', NULL, 1),
(7238169, 1119866, 58634, '<td valign="top">What a macro! The colors are so vivid and beautiful. Awesome shot!</td>', 'What a macro! The colors are so vivid and beautiful. Awesome shot!', '2014-07-07 20:00:45.000000', NULL, 1),
(7238170, 1119851, 58634, '<td valign="top">I can feel his struggle.</td>', 'I can feel his struggle.', '2014-07-07 20:00:57.000000', NULL, 1),
